structureCode.vanilla:
const regiao = document.createElement('div');
regiao.setAttribute('role', 'status');
regiao.setAttribute('aria-busy', String(isLoading));
regiao.setAttribute('aria-label', 'Carregando lista');
regiao.append(
  createSkeleton({ shape: 'avatar' }),
  createSkeleton({ shape: 'text', width: '3-4' }),
);

extensibilityCode.vanilla:
// Forma e dimensão por atributo — a folha de estilo continua dona das medidas
createSkeleton({ shape: 'avatar', size: 'lg' });
createSkeleton({ shape: 'text', width: '3-4' });
createSkeleton({ shape: 'fill' });

customizationCode.web:
/* Cor do placeholder em um tema custom */
.nds-skeleton {
  background-color: hsl(var(--muted) / 0.6);
}

/* Pulso mais curto */
.nds-skeleton {
  animation-duration: 1s;
}

